<script setup lang="ts">
import { computed,ref } from 'vue'
import PageHeader from '../components/layout/PageHeader.vue'
import FieldLevelTable from '../components/field/FieldLevelTable.vue'
import StatCard from '../components/common/StatCard.vue'
import Toast from '../components/common/Toast.vue'
import ConfirmDialog from '../components/common/ConfirmDialog.vue'
import { useTaskStore } from '../stores/taskStore'
import { useFieldLevelStore } from '../stores/fieldLevelStore'
const task=useTaskStore(),store=useFieldLevelStore(),search=ref(''),group=ref(''),required=ref(''),dimension=ref(''),level=ref(''),reset=ref(false)
const filtered=computed(()=>store.levels.filter(f=>(!search.value||`${f.field} ${f.key}`.includes(search.value))&&(!group.value||f.group===group.value)&&(!required.value||f.platformRequired===required.value)&&(!dimension.value||(dimension.value==='vector'?f.vectorRequirement!=='optional':dimension.value==='derived'?f.derivable:dimension.value==='default'?f.defaultable:dimension.value==='manual'?f.manualFill||f.allowEmpty:f.platformRequired==='unknown'))&&(!level.value||(['plot_code','geom_wkt'].includes(f.key)||f.platformRequired==='yes'?'block':f.platformRequired==='unknown'?'info':!f.allowEmpty?'warn':'none')===level.value)))
</script>
<template><PageHeader eyebrow="TEMPLATE / FIELD POLICY" :title="`${task.profile.name} · 字段配置`" description="五类处理维度可同时适用。默认值只填补空值，平台必填未确认时不阻断。"><button class="secondary" @click="reset=true">恢复默认</button><RouterLink class="button" :to="task.path('mapping')">下一步：映射确认 →</RouterLink></PageHeader><div class="stats-grid"><StatCard label="模板字段" :value="store.levels.length"/><StatCard label="矢量必需" :value="store.levels.filter(f=>f.vectorRequirement==='required').length"/><StatCard label="系统可推导" :value="store.levels.filter(f=>f.derivable).length"/><StatCard label="允许空值" :value="store.levels.filter(f=>f.allowEmpty).length"/></div><Toast :message="store.notice"/><section class="panel"><div class="filters"><input v-model="search" aria-label="搜索字段" placeholder="搜索字段名称或 key"><select v-model="group" aria-label="字段组"><option value="">全部分组</option><option value="basic">基本信息</option><option value="confirm">确权信息</option><option value="ext">扩展信息</option></select><select v-model="dimension" aria-label="处理维度"><option value="">全部处理维度</option><option value="vector">矢量必需 / 建议</option><option value="derived">系统可推导</option><option value="default">项目可默认</option><option value="manual">人工补 / 允许空</option><option value="unknown">平台必填待确认</option></select><select v-model="required" aria-label="平台必填筛选"><option value="">全部必填状态</option><option value="unknown">待确认</option><option value="yes">已确认必填</option><option value="no">非必填</option></select><select v-model="level" aria-label="缺失级别"><option value="">全部级别</option><option value="block">阻断</option><option value="warn">警告</option><option value="info">提示</option></select></div><FieldLevelTable :levels="filtered" @update="store.update"/></section><p class="hint">模板中的“必填”字样作为待核实依据保留。切换“已确认必填”仍需满足字段所列适用条件；确权状态可在三表详情中人工确认。几何及关联键遵循独立结构规则。</p><ConfirmDialog v-if="reset" title="恢复默认字段配置？" message="将覆盖当前浏览器保存的默认值、允许空和平台必填配置。" @cancel="reset=false" @confirm="store.reset();reset=false"/></template>
